<?php /** @var array $sources @var array $packages @var array|null $release @var string $policy @var array $policies @var array $history @var \Core\Security\Csrf $csrf @var string $basePath */ ?>
<div class="card"><div class="card-heading"><div><h2>Managed core updates</h2><p class="muted">Catalog metadata and downloaded update archives must both pass Ed25519 trust verification. Automatic apply creates a full safety backup and maintenance window first.</p></div><?php if($release): ?><span class="badge <?= version_compare($release['version'],WC_VERSION,'>')?'warn':'ok' ?>">Latest <?= e($release['version']) ?></span><?php endif; ?></div><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="policy"><label>Automation policy</label><div class="inline-fields"><select name="policy"><?php foreach($policies as $option): ?><option value="<?= e_attr($option) ?>" <?= $policy===$option?'selected':'' ?>><?= e(ucwords(str_replace('-',' ',$option))) ?></option><?php endforeach; ?></select><button class="btn">Save policy</button></div></form><p class="muted"><strong>Stage</strong> downloads and verifies for owner review. <strong>Apply</strong> additionally backs up, enables maintenance, applies files and runs migrations. Security policies act only on releases marked security by the signed feed.</p><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="check_updates"><button class="btn secondary">Check trusted feeds and stage latest</button> <a class="btn secondary" href="<?= e_attr($basePath) ?>/admin/updates">Open staged update</a></form></div>
<div class="card"><div class="card-heading"><div><p class="section-kicker">Trust roots</p><h2>Signed catalog sources</h2><p class="card-subtitle">Only verified catalog metadata is displayed. Package archives are independently inspected before installation.</p></div></div><?php if($sources): ?><table><tr><th>Source</th><th>URL</th><th>Status</th><th>Checked</th><th></th></tr><?php foreach($sources as $source): ?><tr><td><strong><?= e($source['label']) ?></strong></td><td><code class="break-all"><?= e($source['catalog_url']) ?></code></td><td><?= !$source['active']?'<span class="badge neutral">disabled</span>':($source['last_error']?'<span class="badge bad">error</span>':'<span class="badge ok">trusted</span>') ?><?php if($source['last_error']): ?><br><small class="err"><?= e($source['last_error']) ?></small><?php endif; ?></td><td><?= e($source['last_checked_at']??'Never') ?></td><td><div class="button-row compact"><?php if($source['active']): ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="source_refresh"><input type="hidden" name="id" value="<?= (int)$source['id'] ?>"><button class="btn small">Refresh</button></form><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="source_disable"><input type="hidden" name="id" value="<?= (int)$source['id'] ?>"><button class="btn small danger" data-confirm="Disable this catalog source? Cached entries will stop appearing.">Disable</button></form><?php else: ?><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="source_enable"><input type="hidden" name="id" value="<?= (int)$source['id'] ?>"><button class="btn small">Enable</button></form><form method="post"><?= $csrf->field() ?><input type="hidden" name="action" value="source_remove"><input type="hidden" name="id" value="<?= (int)$source['id'] ?>"><button class="btn small danger" data-confirm="Permanently remove this disabled catalog source and cached metadata?">Remove</button></form><?php endif; ?></div></td></tr><?php endforeach; ?></table><?php else: ?><div class="empty-state"><strong>No catalog sources</strong><span>Add a publisher’s signed HTTPS catalog to discover verified releases.</span></div><?php endif; ?><details class="disclosure"><summary class="btn secondary">Add signed catalog</summary><form method="post" class="disclosure-body"><?= $csrf->field() ?><input type="hidden" name="action" value="source_add"><div class="inline-fields"><div><label>Label</label><input name="label" maxlength="120" required></div><div><label>Catalog HTTPS URL</label><input type="url" name="catalog_url" maxlength="500" required></div></div><button class="btn">Add source</button></form></details></div>
<div class="card"><h2 style="margin-top:0">Package catalog</h2><?php if(!$packages): ?><div class="empty-state">Refresh a trusted catalog to see industries, add-ons and themes.</div><?php else: ?><div class="result-list"><?php foreach($packages as $package): ?><div class="result-row"><div style="flex:1"><strong><?= e($package['name']) ?></strong><small><?= e($package['type']) ?> · <?= e($package['package_id']) ?> · v<?= e($package['version']) ?> · <?= e($package['source']) ?></small><p class="muted"><?= e($package['description']) ?></p></div><a class="btn small secondary" href="<?= e_url($package['download_url']) ?>" target="_blank" rel="noopener noreferrer">Download</a></div><?php endforeach; ?></div><?php endif; ?></div>
<?php if($history): ?><div class="card"><h2 style="margin-top:0">Managed update history</h2><table><tr><th>Time</th><th>Source</th><th>Version</th><th>Action</th><th>Status</th><th>Detail</th></tr><?php foreach($history as $row): ?><tr><td><?= e($row['created_at']) ?></td><td><?= e($row['source']??'—') ?></td><td><?= e($row['version']??'—') ?></td><td><?= e($row['action']) ?></td><td><span class="badge <?= $row['status']==='ok'?'ok':'bad' ?>"><?= e($row['status']) ?></span></td><td><?= e($row['detail']) ?></td></tr><?php endforeach; ?></table></div><?php endif; ?>
